function useTypewriter(words, speed = 55, pause = 1500) {
  const [text, setText] = useState("");
  const [wordIdx, setWordIdx] = useState(0);
  const [deleting, setDeleting] = useState(false);

  useEffect(() => {
    const current = words[wordIdx];
    let timeout;
    if (!deleting && text.length < current.length) {
      timeout = setTimeout(() => setText(current.slice(0, text.length + 1)), speed);
    } else if (!deleting && text.length === current.length) {
      timeout = setTimeout(() => setDeleting(true), pause);
    } else if (deleting && text.length > 0) {
      timeout = setTimeout(() => setText(current.slice(0, text.length - 1)), speed / 1.6);
    } else if (deleting && text.length === 0) {
      setDeleting(false);
      setWordIdx((i) => (i + 1) % words.length);
    }
    return () => clearTimeout(timeout);
  }, [text, deleting, wordIdx, words, speed, pause]);

  return text;
}

function NavBar({ active, mobileOpen, setMobileOpen, theme, toggleTheme }) {
  const [solid, setSolid] = useState(false);
  useEffect(() => {
    const handler = () => setSolid(window.scrollY > 40);
    window.addEventListener("scroll", handler, { passive: true });
    handler();
    return () => window.removeEventListener("scroll", handler);
  }, []);

  const go = (id) => {
    setMobileOpen(false);
    const el = document.getElementById(id);
    if (el) el.scrollIntoView({ behavior: "smooth", block: "start" });
  };

  return (
    <header
      className={"nav" + (solid ? " nav--solid" : "")}
      role="banner"
    >
      <nav className="nav__inner" aria-label="Primary">
        <button className="nav__brand" onClick={() => go("home")} aria-label="Go to top">
          NR<span className="nav__brand-dot">.</span>
        </button>

        <ul className="nav__links">
          {NAV_ITEMS.map((item) => (
            <li key={item.id}>
              <button
                className={"nav__link" + (active === item.id ? " nav__link--active" : "")}
                onClick={() => go(item.id)}
              >
                {item.label}
              </button>
            </li>
          ))}
        </ul>

        <button
          className="nav__theme-toggle"
          onClick={toggleTheme}
          aria-label={theme === "dark" ? "Switch to light theme" : "Switch to dark theme"}
          title={theme === "dark" ? "Switch to light theme" : "Switch to dark theme"}
        >
          {theme === "dark" ? <IconSun className="nav__theme-icon" /> : <IconMoon className="nav__theme-icon" />}
        </button>

        <a className="btn btn--ghost nav__resume" href={RESUME_DATA_URI} download="Nitish_Raj_Resume.pdf">
          Resume
        </a>

        <button
          className="nav__burger"
          aria-label={mobileOpen ? "Close menu" : "Open menu"}
          aria-expanded={mobileOpen}
          onClick={() => setMobileOpen((v) => !v)}
        >
          <span />
          <span />
          <span />
        </button>
      </nav>

      <div className={"nav__drawer" + (mobileOpen ? " nav__drawer--open" : "")}>
        <ul>
          {NAV_ITEMS.map((item) => (
            <li key={item.id}>
              <button onClick={() => go(item.id)}>{item.label}</button>
            </li>
          ))}
          <li>
            <a href={RESUME_DATA_URI} download="Nitish_Raj_Resume.pdf" style={{ display: "block", padding: "12px 0" }}>
              Download resume
            </a>
          </li>
          <li>
            <button onClick={toggleTheme} style={{ display: "flex", alignItems: "center", gap: "10px", width: "100%" }}>
              {theme === "dark" ? <IconSun className="nav__theme-icon" /> : <IconMoon className="nav__theme-icon" />}
              {theme === "dark" ? "Light theme" : "Dark theme"}
            </button>
          </li>
        </ul>
      </div>
    </header>
  );
}

