function CopyableRow({ icon, value, displayValue, label }) {
  const [copied, setCopied] = useState(false);

  const handleCopy = async () => {
    try {
      await navigator.clipboard.writeText(value);
    } catch {
      // Fallback for environments without clipboard API access
      const el = document.createElement("textarea");
      el.value = value;
      document.body.appendChild(el);
      el.select();
      try {
        document.execCommand("copy");
      } catch {}
      document.body.removeChild(el);
    }
    setCopied(true);
    setTimeout(() => setCopied(false), 1800);
  };

  return (
    <button
      type="button"
      className={"contact-row contact-row--button" + (copied ? " contact-row--copied" : "")}
      onClick={handleCopy}
      aria-label={`Copy ${label}`}
    >
      {icon}
      <span>{displayValue}</span>
      <span className="contact-row__copy-cue" aria-hidden="true">
        {copied ? <IconCheck className="contact-row__copy-icon" /> : <IconCopy className="contact-row__copy-icon" />}
        {copied ? "Copied" : "Copy"}
      </span>
    </button>
  );
}

function Contact() {
  const [form, setForm] = useState({ name: "", email: "", message: "" });
  const [sent, setSent] = useState(false);

  const submit = (e) => {
    e.preventDefault();
    const subject = encodeURIComponent(`Portfolio enquiry from ${form.name || "a visitor"}`);
    const body = encodeURIComponent(`${form.message}\n\n— ${form.name} (${form.email})`);
    window.location.href = `mailto:${LINKS.email}?subject=${subject}&body=${body}`;
    setSent(true);
  };

  return (
    <section id="contact" className="section">
      <SectionHeading kicker="Contact" title="Let's build something" />
      <div className="contact__grid">
        <Reveal className="contact__details">
          <p className="contact__intro">
            Open to full-time roles, internships, and research or project collaborations.
            The fastest way to reach me is email — I check it daily.
          </p>
          <CopyableRow
            icon={<IconMail className="contact-row__icon" />}
            value={LINKS.email}
            displayValue={LINKS.email}
            label="email address"
          />
          <CopyableRow
            icon={<IconPhone className="contact-row__icon" />}
            value={LINKS.phone}
            displayValue={LINKS.phone}
            label="phone number"
          />
          <a className="contact-row" href={LINKS.linkedin} target="_blank" rel="noreferrer">
            <IconLinkedin className="contact-row__icon" />
            <span>linkedin.com/in/jmnitishraj3325</span>
          </a>
          <a className="contact-row" href={LINKS.github} target="_blank" rel="noreferrer">
            <IconGithub className="contact-row__icon" />
            <span>github.com/Nitish-jm25</span>
          </a>
        </Reveal>

        <Reveal delay={120} className="contact-form-wrap">
          <form className="contact-form" onSubmit={submit}>
            <label className="field">
              <span className="field-label">Name</span>
              <input
                required
                value={form.name}
                onChange={(e) => setForm({ ...form, name: e.target.value })}
                type="text"
                placeholder="Your name"
              />
            </label>
            <label className="field">
              <span className="field-label">Email</span>
              <input
                required
                value={form.email}
                onChange={(e) => setForm({ ...form, email: e.target.value })}
                type="email"
                placeholder="you@email.com"
              />
            </label>
            <label className="field">
              <span className="field-label">Message</span>
              <textarea
                required
                value={form.message}
                onChange={(e) => setForm({ ...form, message: e.target.value })}
                rows={4}
                placeholder="What are you building?"
              />
            </label>
            <button className="btn btn--primary contact-form__submit" type="submit">
              {sent ? "Opening your mail app…" : "Send message"}
              <IconArrow className="btn__icon" />
            </button>
          </form>
        </Reveal>
      </div>
    </section>
  );
}

